"""Throwaway inspection helper: compact text view of an .xlsx or .docx using stdlib only."""
import re
import sys
import zipfile
import xml.etree.ElementTree as ET

sys.stdout.reconfigure(encoding="utf-8")
path = sys.argv[1]
z = zipfile.ZipFile(path)
names = z.namelist()
print("##", path)
print("members:", names)


def local(tag):
    return tag.rsplit("}", 1)[-1]


if path.lower().endswith(".xlsx"):
    wb = z.read("xl/workbook.xml").decode("utf-8")
    print("\nSHEETS:", re.findall(r"<sheet [^>]*>", wb))
    shared = []
    if "xl/sharedStrings.xml" in names:
        root = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in root:
            shared.append("".join(t.text or "" for t in si.iter() if local(t.tag) == "t"))
    for n in sorted(x for x in names if x.startswith("xl/worksheets/sheet")):
        root = ET.fromstring(z.read(n))
        print(f"\n---- {n} ----")
        for el in root.iter():
            lt = local(el.tag)
            if lt == "row":
                cells = []
                for c in el:
                    ref = c.get("r")
                    t = c.get("t")
                    s = c.get("s")
                    v = None
                    for ch in c.iter():
                        if local(ch.tag) == "v":
                            v = ch.text
                        elif local(ch.tag) == "t":
                            v = (v or "") + (ch.text or "")
                    if t == "s" and v is not None:
                        v = shared[int(v)]
                    if v not in (None, ""):
                        cells.append(f"{ref}{'*' if s and s != '0' else ''}={v!r}")
                attrs = {k: el.get(k) for k in ("hidden", "outlineLevel") if el.get(k)}
                print(f"row {el.get('r')} {attrs or ''}: " + " | ".join(cells))
            elif lt in ("mergeCell", "col", "sheetView", "autoFilter", "tabColor"):
                print(f"<{lt} {dict(el.attrib)}>")
    extra = [x for x in names if "comments" in x or "drawing" in x or "media" in x]
    print("\nextra parts:", extra)
else:
    for n in names:
        if n.startswith("word/") and n.endswith(".xml") and not n.startswith("word/theme"):
            x = z.read(n).decode("utf-8", "replace")
            print(f"\n---- {n} ({len(x)} chars) ----")
            if n in ("word/document.xml",) or "header" in n or "footer" in n or "comments" in n or "footnotes" in n:
                x = re.sub(r">\s*<", ">\n<", x)
                print(x)

