"""The only code that talks to the model provider (OpenAI Responses API).

complete() answers from the cache when it can, calls the provider when it must, and
raises LLMUnavailable when it can do neither. Callers catch LLMUnavailable and degrade;
nothing here is allowed to crash a run.
"""

from __future__ import annotations

import base64
import json
import os

from .cache import ResponseCache, request_key

DEFAULT_MODEL = "gpt-6.1-terra"

# USD per 1M tokens as (input, cached input, output). Standard tier, read from
# https://developers.openai.com/api/docs/pricing on 2026-11-14.
PRICES = {
    "gpt-6-astra": (10.00, 1.00, 50.00),
    "gpt-6.1-sol": (2.00, 0.10, 10.00),
    "gpt-6.1-terra": (1.00, 0.05, 5.00),
    "gpt-6-luna": (0.10, 0.01, 0.50),
}


class LLMUnavailable(Exception):
    """No cached answer and no way to get one: no key, provider error, or unusable output."""


def text_part(text: str) -> dict:
    return {"type": "input_text", "text": text}


def image_part(data: bytes, mime: str, detail: str = "high") -> dict:
    return {"type": "input_image", "image_url": _data_url(data, mime), "detail": detail}


def pdf_part(data: bytes) -> dict:
    # A fixed filename keeps the cache key a function of the file's bytes only.
    return {"type": "input_file", "filename": "document.pdf", "file_data": _data_url(data, "application/pdf")}


def _data_url(data: bytes, mime: str) -> str:
    return f"data:{mime};base64,{base64.b64encode(data).decode('ascii')}"


def cost_usd(model: str, usage: dict) -> float | None:
    """Dollar cost of one call, or None when the model's price is not in PRICES."""
    if model not in PRICES:
        return None
    price_in, price_cached, price_out = PRICES[model]
    cached = usage["cached_input_tokens"]
    fresh = usage["input_tokens"] - cached
    return (fresh * price_in + cached * price_cached + usage["output_tokens"] * price_out) / 1_000_000


class LLMClient:
    def __init__(
        self,
        model: str | None = None,
        cache: ResponseCache | None = None,
        api_key: str | None = None,
        reasoning_effort: str = "low",
    ):
        self.model = model or os.environ.get("RFQ_LLM_MODEL") or DEFAULT_MODEL
        self.reasoning_effort = reasoning_effort
        self.cache = cache or ResponseCache()
        self._api_key = api_key or os.environ.get("OPENAI_API_KEY")
        self._openai = None
        # One record per complete() call, cached or live. The cost report is built from this.
        self.calls: list[dict] = []

    def complete(self, *, task: str, label: str, instructions: str, content: list[dict], schema: dict) -> dict:
        """Return the model's JSON answer for this request. `label` is the email id, for the ledger."""
        request = {
            "model": self.model,
            "instructions": instructions,
            "input": [{"role": "user", "content": content}],
            "text": {"format": {"type": "json_schema", "name": task, "strict": True, "schema": schema}},
            "reasoning": {"effort": self.reasoning_effort},
            "store": False,  # customer emails are not kept on the provider's side
        }
        key = request_key(request)
        entry = self.cache.get(key)
        from_cache = entry is not None
        if not from_cache:
            entry = {"task": task, "label": label, "model": self.model, **self._call_provider(request)}
            self.cache.put(key, entry)
        self.calls.append(
            {
                "label": label,
                "task": task,
                "model": entry["model"],
                "from_cache": from_cache,
                "usage": entry["usage"],
                "cost_usd": cost_usd(entry["model"], entry["usage"]),
            }
        )
        return entry["output"]

    def _call_provider(self, request: dict) -> dict:
        if not self._api_key:
            raise LLMUnavailable("OPENAI_API_KEY is not set and this request is not in the cache")
        try:
            response = self._client().responses.create(**request)
        except Exception as exc:
            # Only the error type and HTTP status are kept: provider messages can echo the key.
            status = getattr(exc, "status_code", None)
            raise LLMUnavailable(f"provider call failed: {type(exc).__name__} (status {status})") from exc
        if response.status != "completed":
            raise LLMUnavailable(f"provider response was {response.status}, not completed")
        try:
            output = json.loads(response.output_text)
        except ValueError as exc:  # a refusal or cut-off answer is not valid JSON
            raise LLMUnavailable("model answer was not valid JSON") from exc
        details = getattr(response.usage, "input_tokens_details", None)
        return {
            "output": output,
            "usage": {
                "input_tokens": response.usage.input_tokens,
                "cached_input_tokens": getattr(details, "cached_tokens", 0) or 0,
                "output_tokens": response.usage.output_tokens,
            },
        }

    def _client(self):
        if self._openai is None:
            from openai import OpenAI  # imported late: a cached replay does not need the SDK

            self._openai = OpenAI(api_key=self._api_key, timeout=120, max_retries=3)
        return self._openai

