class AttachmentExtractor:
    def __init__(self, llm: LLMClient | None = None):
        self.llm = llm

    def extract(self, *, label: str, filename: str, mime: str, data: bytes, depth: int = 0) -> dict:
        """`label` is the email id, used for the model call ledger."""
        file_type = "unknown"
        try:
            file_type = sniff(data, filename, mime)
            return self._extract(file_type, label, filename, data, depth)
        except Unreadable as exc:
            return unreadable(filename, str(exc), file_type)
        except Exception as exc:  # damaged file: report it, never raise
            return unreadable(filename, f"file could not be opened ({type(exc).__name__})", file_type)

    def _extract(self, file_type: str, label: str, filename: str, data: bytes, depth: int) -> dict:
        if file_type in _UNSUPPORTED:
            raise Unreadable(_UNSUPPORTED[file_type])
        if file_type in _CODE_READERS:
            return self._from_code(filename, file_type, _CODE_READERS[file_type](data))
        if file_type == "pdf":
            text, pages = readers.read_pdf(data)
            if text is not None:
                return self._from_code(filename, file_type, text)
            if pages > MAX_SCANNED_PAGES:
                raise Unreadable(f"scanned PDF has {pages} pages, more than the {MAX_SCANNED_PAGES} sent to the model")
            return self._from_model(label, filename, file_type, "application/pdf", data)
        if file_type in IMAGE_MEDIA_TYPES:
            return self._from_model(label, filename, file_type, IMAGE_MEDIA_TYPES[file_type], data)
        if file_type == "eml":
            return self._from_email(label, filename, data, depth)
        return self._from_zip(label, filename, data, depth)

    @staticmethod
    def _from_code(filename: str, file_type: str, text: str) -> dict:
        if not text.strip():
            raise Unreadable("no readable text in the file")
        return result(filename, file_type, status="ok", method="code", kind="document", text=text)

    def _from_model(self, label: str, filename: str, file_type: str, media_type: str, data: bytes) -> dict:
        if self.llm is None:
            raise Unreadable("needs the model to read it, and no model client was given")
        try:
            answer = transcribe(self.llm, label=label, mime=media_type, data=data)
        except LLMUnavailable as exc:
            raise Unreadable(f"needs the model to read it: {exc}") from exc
        return result(
            filename,
            file_type,
            status="ok",
            method="llm",
            kind=answer["kind"],
            legible=answer["legible"],
            text=answer["text"],
            note=answer["note"],
        )

    def _from_email(self, label: str, filename: str, data: bytes, depth: int) -> dict:
        """An attached message: its headers and body as text, its own attachments as children."""
        message = BytesParser(policy=policy.default).parsebytes(data)
        header = "\n".join(f"{name}: {message[name]}" for name in ("From", "To", "Date", "Subject") if message[name])
        body = message.get_body(preferencelist=("plain", "html"))
        text = body.get_content() if body is not None else ""
        if body is not None and body.get_content_type() == "text/html":
            text = readers.html_to_text(text)
        children = []
        if depth < MAX_DEPTH:
            for part in message.iter_attachments():
                nested = part.get_content_type() == "message/rfc822"
                payload = part.get_payload(0).as_bytes() if nested else part.get_payload(decode=True)
                children.append(
                    self.extract(
                        label=label,
                        filename=part.get_filename() or "unnamed",
                        mime=part.get_content_type(),
                        data=payload or b"",
                        depth=depth + 1,
                    )
                )
        return result(
            filename, "eml", status="ok", method="code", kind="document", text=f"{header}\n\n{text}".strip(), children=children
        )

    def _from_zip(self, label: str, filename: str, data: bytes, depth: int) -> dict:
        if depth >= MAX_DEPTH:
            raise Unreadable("archive is nested too deeply to unpack")
        children = []
        with zipfile.ZipFile(io.BytesIO(data)) as archive:
            members = [m for m in archive.infolist() if not m.is_dir() and not m.filename.startswith("__MACOSX/")]
            if not members:
                raise Unreadable("archive is empty")
            if len(members) > MAX_ARCHIVE_FILES or sum(m.file_size for m in members) > MAX_ARCHIVE_BYTES:
                raise Unreadable("archive is too large to unpack")
            for member in members:
                name = PurePosixPath(member.filename).name
                try:
                    payload = archive.read(member)
                except Exception as exc:  # a password-protected or damaged member
                    children.append(unreadable(name, f"could not be unpacked from the archive ({type(exc).__name__})"))
                    continue
                children.append(self.extract(label=label, filename=name, mime="", data=payload, depth=depth + 1))
        return result(filename, "zip", status="ok", method="code", kind="document", children=children)

def read_xlsx(data: bytes) -> str:
    workbook = openpyxl.load_workbook(io.BytesIO(data), data_only=True)
    blocks = []
    for sheet in workbook.worksheets:
        hidden = " - HIDDEN SHEET" if sheet.sheet_state != "visible" else ""
        lines = [f'[sheet "{sheet.title}"{hidden}]']
        fill = _vertical_merge_values(sheet)
        for row in sheet.iter_rows():
            cells = [_cell_text(cell) or fill.get((cell.row, cell.column), "") for cell in row]
            while cells and not cells[-1]:
                cells.pop()
            if not cells:
                continue
            line = " | ".join(cells)
            if sheet.row_dimensions[row[0].row].hidden:
                line = "[hidden row] " + line
            lines.append(line)
        blocks.append("\n".join(lines))
    return "\n\n".join(blocks)


def _cell_text(cell) -> str:
    value = cell.value
    if value is None:
        return ""
    if isinstance(value, float) and value.is_integer():
        value = int(value)
    if isinstance(value, datetime) and value.time() == value.min.time():
        value = value.date()
    text = " ".join(str(value).split())
    if text and cell.font is not None and cell.font.strike:
        text = _strike(text)
    return text


def _vertical_merge_values(sheet) -> dict:
    """A cell merged down several rows applies to each of them, so repeat its text on each row."""
    fill = {}
    for merged in sheet.merged_cells.ranges:
        if merged.max_row == merged.min_row:
            continue
        text = _cell_text(sheet.cell(merged.min_row, merged.min_col))
        for row in range(merged.min_row + 1, merged.max_row + 1):
            fill[(row, merged.min_col)] = text
    return fill


def read_delimited(data: bytes) -> str:
    text = decode_text(data)
    try:
        dialect = csv.Sniffer().sniff(text[:4096], delimiters=",;\t|")
    except csv.Error:
        dialect = csv.excel
    rows = csv.reader(io.StringIO(text), dialect)
    return "\n".join(" | ".join(cell.strip() for cell in row) for row in rows if any(cell.strip() for cell in row))


# --- Word ---------------------------------------------------------------------------------

_W = "{http://schemas.openxmlformats.org/wordprocessingml/2006/main}"


def read_docx(data: bytes) -> str:
    with zipfile.ZipFile(io.BytesIO(data)) as archive:
        root = ElementTree.fromstring(archive.read("word/document.xml"))
    lines = []
    for block in _docx_blocks(root.find(f"{_W}body")):
        if block.tag == f"{_W}p":
            text = _docx_paragraph(block)
            if text:
                lines.append(("# " if _docx_is_heading(block) else "") + text)
        else:
            for row in block.iter(f"{_W}tr"):
                cells = [
                    " ".join(filter(None, (_docx_paragraph(p) for p in cell.iter(f"{_W}p"))))
                    for cell in row.findall(f"{_W}tc")
                ]
                if any(cells):
                    lines.append(" | ".join(cells))
    return "\n".join(lines)


def _docx_blocks(parent):
    """Paragraphs and tables in document order, looking inside content controls."""
    for child in parent if parent is not None else ():
        if child.tag in (f"{_W}p", f"{_W}tbl"):
            yield child
        elif child.tag == f"{_W}sdt":
            yield from _docx_blocks(child.find(f"{_W}sdtContent"))


def _docx_is_heading(paragraph) -> bool:
    style = paragraph.find(f"{_W}pPr/{_W}pStyle")
    name = (style.get(f"{_W}val") or "").lower() if style is not None else ""
    return name.startswith("heading") or name == "title"


def _docx_paragraph(paragraph) -> str:
    pieces = []  # (text, crossed out?)

    def walk(node, deleted):
        for child in node:
            if child.tag == f"{_W}r":
                text = "".join(_docx_run_piece(part) for part in child)
                pieces.append((text, deleted or _docx_run_is_struck(child)))
            elif child.tag in (f"{_W}del", f"{_W}moveFrom"):
                walk(child, True)  # a tracked deletion shows as crossed out in Word
            else:
                walk(child, deleted)

    walk(paragraph, False)
    out = []
    for struck, group in itertools.groupby(pieces, key=lambda piece: piece[1]):
        text = "".join(piece[0] for piece in group)
        out.append(_strike(text.strip()) if struck and text.strip() else text)
    return " ".join("".join(out).split())


def _docx_run_piece(part) -> str:
    if part.tag in (f"{_W}t", f"{_W}delText"):
        return part.text or ""
    if part.tag in (f"{_W}tab", f"{_W}br"):
        return " "
    return ""


def _docx_run_is_struck(run) -> bool:
    for tag in ("strike", "dstrike"):
        mark = run.find(f"{_W}rPr/{_W}{tag}")
        if mark is not None and mark.get(f"{_W}val") not in ("0", "false"):
            return True
    return False


# --- PDF ----------------------------------------------------------------------------------


def read_pdf(data: bytes) -> tuple[str | None, int]:
    """Return (text, page count). The text is None when a page is a scan and needs a model."""
    reader = PdfReader(io.BytesIO(data))
    if reader.is_encrypted:
        try:
            opened = reader.decrypt("")  # some PDFs are "protected" with an empty password
        except Exception:
            opened = 0
        if not opened:
            raise Unreadable("PDF is password-protected")
    pages = []
    for page in reader.pages:
        text = _pdf_page_text(page)
        if len(text) < MIN_PAGE_TEXT and _pdf_page_has_image(page):
            return None, len(reader.pages)
        pages.append(text)
    out = [f"--- page {number} ---\n{text}" for number, text in enumerate(pages, 1) if text]
    try:
        fields = {name: field.get("/V") for name, field in (reader.get_fields() or {}).items()}
    except Exception:  # a broken form dictionary must not cost us the page text
        fields = {}
    filled = [f"{name}: {value}" for name, value in fields.items() if value not in (None, "")]
    if filled:  # a fillable form keeps its answers in fields, not in the page text
        out.append("--- form fields ---\n" + "\n".join(filled))
    return "\n".join(out), len(reader.pages)


def _pdf_page_text(page) -> str:
    """Layout mode keeps a table row on one line; the gaps between columns become " | "."""
    try:
        text = page.extract_text(extraction_mode="layout")
    except Exception:
        text = page.extract_text()
    lines = (re.sub(r" {2,}", " | ", line.strip()) for line in (text or "").splitlines())
    return "\n".join(line for line in lines if line)


def _pdf_page_has_image(page) -> bool:
    try:
        xobjects = page["/Resources"]["/XObject"]
        return any(xobjects[name].get("/Subtype") == "/Image" for name in xobjects)
    except Exception:
        return False


# --- HTML and plain text ------------------------------------------------------------------

class MimeParser:
    """Parse every .eml in a directory. One bad email never stops the others."""

    def __init__(self, files_dir: Path | None = None, extractor: AttachmentExtractor | None = None):
        # Attachment bytes are written under files_dir/<email id>/<filename>.
        # With an extractor and no files_dir, a temporary directory is used and removed afterwards.
        # With neither, only attachment metadata is returned and nothing is written.
        self.extractor = extractor
        self._temp_dir = None
        if files_dir is None and extractor is not None:
            self._temp_dir = tempfile.TemporaryDirectory(prefix="rfq_attachments_")
            files_dir = self._temp_dir.name
        self.files_dir = Path(files_dir) if files_dir else None

    def parse_file(self, path: Path) -> dict:
        """Return one email as a dict. `error` is None unless the email could not be read.

        With an extractor, each attachment gains an `extraction` dict (see attachments/extractor.py).
        """
        path = Path(path)
        try:
            email = {**eml_to_json(path, self.files_dir), "error": None}
        except Exception as exc:  # a broken .eml is recorded, not raised
            return {
                "id": path.stem,
                "headers": {},
                "text": None,
                "html": None,
                "attachments": [],
                "error": f"{type(exc).__name__}: {exc}",
            }
        if self.extractor is not None:
            for attachment in email["attachments"]:
                attachment["extraction"] = self._extract(email["id"], attachment)
        return email

    def _extract(self, email_id: str, attachment: dict) -> dict:
        try:
            data = Path(attachment["path"]).read_bytes()
        except OSError as exc:
            return unreadable(attachment["filename"], f"attachment bytes could not be read ({type(exc).__name__})")
        return self.extractor.extract(
            label=email_id, filename=attachment["filename"], mime=attachment["mime"], data=data
        )

    def parse_dir(self, emails_dir: Path) -> dict[str, dict]:
        """Return every .eml in the directory, keyed by filename stem, in name order."""
        return {p.stem: self.parse_file(p) for p in sorted(Path(emails_dir).glob("*.eml"))}

