def html_to_text(html: str) -> str:
    """Text of an HTML document. Lines inside <blockquote> get "> " marks, as plain-text mail has."""
    parser = _HtmlToText()
    parser.feed(html)
    parser.close()
    depth, lines = 0, []
    for raw in "".join(parser.out).splitlines():
        if raw == _QUOTE_OPEN:
            depth += 1
        elif raw == _QUOTE_CLOSE:
            depth = max(0, depth - 1)
        else:
            line = " ".join(raw.split())
            if line:
                lines.append("> " * depth + line)
    return "\n".join(lines)

