        qty = line["qty"]
        if isinstance(qty, float) and qty.is_integer():
            qty = int(qty)
        return {
            "raw": line["raw"],
            "description": line["description"],
            "qty": qty,
            "uom": line["uom"],
            "source": line["source"],
            **self.match(line["description"]),
        }

